"""Hand-written few-shot pool. NOT drawn from eval/questions.jsonl (a test enforces zero overlap), so dev AND test stay clean.
Patterns chosen to cover common LLM failure modes: fan-out joins (COUNT DISTINCT), LEFT JOIN with zero counts,
window functions, set operations, date handling in SQLite, returning exactly the requested columns.
"""

POOL: list[tuple[str, str]] = [
    ("How many customers are there in each country? Return country and customer count.",
     "SELECT Country, COUNT(*) FROM Customer GROUP BY Country"),
    ("List the names of tracks composed by 'Steve Harris'.",
     "SELECT Name FROM Track WHERE Composer = 'Steve Harris'"),
    ("For each artist, how many albums and how many tracks do they have? Return artist name, album count, and track count.",
     "SELECT Artist.Name, COUNT(DISTINCT Album.AlbumId), COUNT(Track.TrackId) FROM Artist JOIN Album ON Album.ArtistId = Artist.ArtistId JOIN Track ON Track.AlbumId = Album.AlbumId GROUP BY Artist.ArtistId, Artist.Name"),
    ("For each genre, what is the longest track? Return genre name and track name. Break ties arbitrarily by keeping one row per genre.",
     "WITH r AS (SELECT Genre.Name AS g, Track.Name AS t, ROW_NUMBER() OVER (PARTITION BY Genre.GenreId ORDER BY Track.Milliseconds DESC, Track.TrackId) AS rn FROM Track JOIN Genre ON Genre.GenreId = Track.GenreId) SELECT g, t FROM r WHERE rn = 1"),
    ("Which customers made no purchases in 2025? Return first name and last name.",
     "SELECT FirstName, LastName FROM Customer WHERE CustomerId NOT IN (SELECT CustomerId FROM Invoice WHERE strftime('%Y', InvoiceDate) = '2025')"),
    ("What was the invoice revenue in each quarter of 2022? Return quarter number (1-4) and revenue.",
     "SELECT (CAST(strftime('%m', InvoiceDate) AS INTEGER) + 2) / 3 AS q, SUM(Total) FROM Invoice WHERE strftime('%Y', InvoiceDate) = '2022' GROUP BY q"),
    ("Which media types are used by tracks priced at 0.99 and also by tracks priced at 1.99? Return media type name.",
     "SELECT MediaType.Name FROM MediaType JOIN Track ON Track.MediaTypeId = MediaType.MediaTypeId WHERE Track.UnitPrice = 0.99 INTERSECT SELECT MediaType.Name FROM MediaType JOIN Track ON Track.MediaTypeId = MediaType.MediaTypeId WHERE Track.UnitPrice = 1.99"),
    ("Which customers have the same support representative as the customer Frank Harris? Return first name and last name, excluding Frank Harris himself.",
     "SELECT FirstName, LastName FROM Customer WHERE SupportRepId = (SELECT SupportRepId FROM Customer WHERE FirstName = 'Frank' AND LastName = 'Harris') AND NOT (FirstName = 'Frank' AND LastName = 'Harris')"),
    ("What percentage of invoices have a total above 5? Return a number from 0 to 100.",
     "SELECT 100.0 * SUM(CASE WHEN Total > 5 THEN 1 ELSE 0 END) / COUNT(*) FROM Invoice"),
    ("What are the 3 most expensive tracks by unit price? Break ties alphabetically by track name. Return track name and unit price.",
     "SELECT Name, UnitPrice FROM Track ORDER BY UnitPrice DESC, Name LIMIT 3"),
    ("Which albums have an average track length above 6 minutes? Return album title.",
     "SELECT Album.Title FROM Album JOIN Track ON Track.AlbumId = Album.AlbumId GROUP BY Album.AlbumId, Album.Title HAVING AVG(Track.Milliseconds) > 360000"),
    ("List the artists whose name is longer than 25 characters. Return artist name.",
     "SELECT Name FROM Artist WHERE LENGTH(Name) > 25"),
    ("How many distinct customers bought tracks by the artist 'Queen'?",
     "SELECT COUNT(DISTINCT Invoice.CustomerId) FROM Invoice JOIN InvoiceLine ON InvoiceLine.InvoiceId = Invoice.InvoiceId JOIN Track ON Track.TrackId = InvoiceLine.TrackId JOIN Album ON Album.AlbumId = Track.AlbumId JOIN Artist ON Artist.ArtistId = Album.ArtistId WHERE Artist.Name = 'Queen'"),
    ("For each billing country, how many invoices were under 5 and how many were 5 or more? Return country, count under 5, count 5 or more.",
     "SELECT BillingCountry, SUM(CASE WHEN Total < 5 THEN 1 ELSE 0 END), SUM(CASE WHEN Total >= 5 THEN 1 ELSE 0 END) FROM Invoice GROUP BY BillingCountry"),
    ("List every genre with its number of tracks, including genres that have no tracks. Return genre name and track count.",
     "SELECT Genre.Name, COUNT(Track.TrackId) FROM Genre LEFT JOIN Track ON Track.GenreId = Genre.GenreId GROUP BY Genre.GenreId, Genre.Name"),
    ("What is the average number of albums per artist, counting only artists who have at least one album?",
     "SELECT AVG(c) FROM (SELECT COUNT(*) AS c FROM Album GROUP BY ArtistId)"),
    ("What is the most expensive track price within each media type? Return media type name and price.",
     "SELECT MediaType.Name, MAX(Track.UnitPrice) FROM Track JOIN MediaType ON MediaType.MediaTypeId = Track.MediaTypeId GROUP BY MediaType.MediaTypeId, MediaType.Name"),
    ("How many days passed between the first and the last invoice?",
     "SELECT CAST(julianday(MAX(InvoiceDate)) - julianday(MIN(InvoiceDate)) AS INTEGER) FROM Invoice"),
    ("List the names of tracks in the playlist named 'Brazilian Music'.",
     "SELECT Track.Name FROM Track JOIN PlaylistTrack ON PlaylistTrack.TrackId = Track.TrackId JOIN Playlist ON Playlist.PlaylistId = PlaylistTrack.PlaylistId WHERE Playlist.Name = 'Brazilian Music'"),
    ("How many tracks are between 3 and 4 minutes long (inclusive)?",
     "SELECT COUNT(*) FROM Track WHERE Milliseconds BETWEEN 180000 AND 240000"),
    ("Return each employee's full name (first and last name joined with a space) as a single column.",
     "SELECT FirstName || ' ' || LastName FROM Employee"),
    ("How many customers have more than one invoice?",
     "SELECT COUNT(*) FROM (SELECT CustomerId FROM Invoice GROUP BY CustomerId HAVING COUNT(*) > 1)"),
    ("Rank the employees by hire date, earliest first, and return first name, last name, and rank. Use RANK.",
     "SELECT FirstName, LastName, RANK() OVER (ORDER BY HireDate) FROM Employee"),
    ("Which artists have more than 3 albums but fewer than 6? Return artist name and album count.",
     "SELECT Artist.Name, COUNT(*) FROM Artist JOIN Album ON Album.ArtistId = Artist.ArtistId GROUP BY Artist.ArtistId, Artist.Name HAVING COUNT(*) > 3 AND COUNT(*) < 6"),
]
